import json, hashlib, subprocess, tarfile
from pathlib import Path
from scripts.study import identity, manifest
root=Path.cwd(); pkg=root/'exploration/stellarator_e2e/generated'; study=root/'exploration/stellarator_e2e/studies/20260917-pre-reveal-feasible-neighborhood'
def sha(b): return hashlib.sha256(b).hexdigest()
def git(*args): return subprocess.check_output(['git',*args],text=True).strip()
snap=json.loads((study/'snapshot.json').read_text()); contract=json.loads((pkg/'contracts/package_contract.json').read_text()); doc=json.loads((study/'results/package_identity.json').read_text())
out={'head':git('rev-parse','HEAD'),'last_model_commit':git('log','-1','--format=%H','--','models'),'last_package_commit':git('log','-1','--format=%H','--','exploration/stellarator_e2e/generated'),'git_status':git('status','--short'),'package_identity_verified':identity.assert_matches(doc,pkg),'sealed_artifact_count':len(contract['artifact_hashes']),'semantic_fingerprint':manifest.read_semantic_fingerprint(pkg),'indicator_input_fingerprint':manifest.indicator_input_fingerprint(pkg),'latest_study_commit':snap['package']['repo_commit'],'current_vs_study_model_package_diff':git('diff',snap['package']['repo_commit'],'--','models','exploration/stellarator_e2e/generated'),'current_vs_r2_base_model_package_diff':git('diff','fe104e8d9db72e5abf86a29262583ce744f62307','--','models','exploration/stellarator_e2e/generated'),'rubric_diff':git('diff','dc0f0b6dc6512b29e1307da647f3a508a1f5356d','--','.project/active/demo-depth-rubric/rubric.md')}
archive=root/'.project/active/aries-comparison-preparation/package/freeze/r2/comparison-freeze.tar.gz'
out['r2_archive_sha256']=sha(archive.read_bytes()); matches=[]; diffs=[]
# Only inspect admitted model/runtime members, not archived source documents.
with tarfile.open(archive,'r:gz') as tf:
 for m in tf.getmembers():
  if m.isfile() and (m.name.startswith('models/') or m.name.startswith('exploration/stellarator_e2e/generated/')):
   p=root/m.name; b=tf.extractfile(m).read()
   (matches if p.is_file() and sha(p.read_bytes())==sha(b) else diffs).append(m.name)
out['r2_model_package_files_equal']=len(matches); out['r2_model_package_differences']=diffs
# Verify retained snapshot artifact references by path/hash only.
checks=[]
def walk(x):
 if isinstance(x,dict):
  if 'path' in x and 'sha256' in x and isinstance(x['path'],str):
   p=study/x['path']
   if not p.is_file(): p=root/x['path']
   if p.is_file(): checks.append({'path':x['path'],'matches':sha(p.read_bytes())==x['sha256']})
  for v in x.values(): walk(v)
 elif isinstance(x,list):
  for v in x: walk(v)
walk(snap)
out['snapshot_hash_checks']={'checked':len(checks),'mismatches':[x for x in checks if not x['matches']]}
Path('/tmp/depth-identity.json').write_text(json.dumps(out,indent=2)+'\n')
print(json.dumps({k:v for k,v in out.items() if k not in ['git_status','indicator_input_fingerprint']},indent=2)); print('indicator',out['indicator_input_fingerprint']['digest'])
